using Finance.Core;
using System.Data;
namespace Finance.Desktop;
internal partial class MainForm
{
    void Invoice(string kind)
    {
        using var f=new Entry(kind+" invoice — manual invoice number"){Width=1150,Height=850};f.Add("Number","Invoice number (manual)");f.Add("Day","Invoice date","date");f.Add("Party","Customer / supplier",choices:Choices("Party",$"Kind='{(kind=="Sales"?"Customer":"Supplier")}' AND Active=1"));f.Add("POS","Place of supply state code");f.Add("Due","Due date","date");f.Add("Reference","PO / reference");f.Add("Remarks","Remarks","multiline");f.Add("Round","Round invoice total to rupee","bool");f.Add("Verified","I verified any manual GST rate","bool");if(kind=="Purchase"){f.Add("ITC","Input GST eligible","bool",value:1);f.Add("Account","Purchase posting account",options:["PURCHASE","EXPENSE","ASSET"]);}
        var parties=(ComboBox)f.Fields["Party"];parties.SelectedIndexChanged+=(_,_)=>Ui.Run(()=>{if(parties.SelectedItem is Choice ch){using var db=engine.Open();var p=db.Row("SELECT * FROM Party WHERE Id=@p0",ch.Id);f.Fields["POS"].Text=kind=="Sales"?Value.Text(p["StateCode"]):Value.Text(db.Scalar("SELECT StateCode FROM Company WHERE Id=1"));((DateTimePicker)f.Fields["Due"]).Value=((DateTimePicker)f.Fields["Day"]).Value.AddDays(Value.Long(p["CreditDays"]));}});
        var lines=new DataTable();lines.Columns.Add("Description");lines.Columns.Add("HSN / SAC");lines.Columns.Add("Quantity",typeof(decimal));lines.Columns.Add("Unit");lines.Columns.Add("Rate (INR)",typeof(decimal));lines.Columns.Add("Discount (INR)",typeof(decimal));lines.Columns.Add("GST %",typeof(decimal));foreach(var key in new[]{"Quantity","Rate (INR)","Discount (INR)","GST %"})lines.Columns[key]!.DefaultValue=key=="Quantity"?1m:key=="GST %"?18m:0m;lines.Rows.Add("","",1m,"Nos",0m,0m,18m);
        var grid=Ui.Grid();grid.ReadOnly=false;grid.AllowUserToAddRows=true;grid.AllowUserToDeleteRows=true;grid.SelectionMode=DataGridViewSelectionMode.CellSelect;grid.DataSource=lines;grid.Dock=DockStyle.Bottom;grid.Height=245;
        var buttons=Bar();buttons.Dock=DockStyle.Bottom;var item=new ComboBox{Width=240,DropDownStyle=ComboBoxStyle.DropDownList};item.Items.AddRange(Choices("Item","Active=1").Cast<object>().ToArray());buttons.Controls.Add(item);buttons.Controls.Add(Ui.Button("Add item",()=>{Value.Require(item.SelectedItem is Choice,"Choose an item.");using var d=engine.Open();var r=d.Row("SELECT * FROM Item WHERE Id=@p0",((Choice)item.SelectedItem!).Id);lines.Rows.Add(Value.Text(r["Name"]),Value.Text(r["HSN"]),1m,Value.Text(r["Unit"]),Value.Rupees(Value.Long(r["Rate"])),0m,Value.Dec(r["GSTRate"]));}));buttons.Controls.Add(Ui.Button("+ Add party",()=>{MasterEdit(kind=="Sales"?"Customer":"Supplier");parties.Items.Clear();parties.Items.AddRange(Choices("Party",$"Kind='{(kind=="Sales"?"Customer":"Supplier")}' AND Active=1").Cast<object>().ToArray());}));
        f.Add("Status","Save as",options:["Posted","Draft"]);f.Controls.Add(grid);f.Controls.Add(buttons);
        f.Finish(x=>{grid.EndEdit();f.BindingContext![lines]!.EndCurrentEdit();var items=new List<InvoiceItem>();foreach(DataRow r in lines.Rows){if(string.IsNullOrWhiteSpace(Value.Text(r[0]))&&Value.Dec(r[4] is DBNull?0:r[4])==0)continue;items.Add(new(Value.Text(r[0]),Value.Text(r[1]),Value.Dec(r[2]),Value.Text(r[3]),Value.Money(Value.Dec(r[4])),Value.Money(Value.Dec(r[5])),Value.Dec(r[6])));}var input=new InvoiceInput(kind,x.S("Number"),x.N("Party"),x.D("Day"),x.D("Due"),x.S("POS"),x.S("Reference"),x.S("Remarks"),items,kind!="Purchase"||x.N("ITC")==1,kind=="Purchase"?x.S("Account"):"PURCHASE",x.N("Round")==1,x.N("Verified")==1);engine.SaveInvoice(input,x.S("Status")=="Posted");},"Save invoice");
        if(parties.Items.Count>0){parties.SelectedIndex=-1;parties.SelectedIndex=0;}f.ShowDialog(this);
    }
    void Movement(bool receipt){string head="";using(var choose=new Entry(receipt?"Receipt head":"Payment head")){choose.Add("Head","Transaction head",options:receipt?Engine.ReceiptHeads:Engine.PaymentHeads.Concat(["FD Investment"]));choose.Finish(x=>head=x.S("Head"),"Continue");if(choose.ShowDialog(this)!=DialogResult.OK)return;}if(head=="FD Investment"){Instrument("FD");return;}
        using var f=new Entry((receipt?"Receipt • ":"Payment • ")+head);f.Add("Day","Transaction date","date");f.Add("Amount","Total amount (INR)","money");f.Add("Bank",receipt?"Received in":"Paid from",choices:Choices("Bank","Active=1"));
        if(head is "Customer Receipt" or "Customer Refund" or "Customer Advance" or "Supplier Payment" or "Supplier Refund")f.Add("Party","Customer / supplier",choices:Choices("Party",$"Kind='{(head.StartsWith("Supplier")?"Supplier":"Customer")}' AND Active=1"));
        if(head is "Staff Advance" or "Staff Advance Refund" or "Employee Advance" or "Employee Advance Refund" or "Employee Loan Repayment" or "Salary/Wages")f.Add("Employee","Employee",choices:Choices("Employee","Active=1"));
        if(head is "Staff Advance" or "Staff Advance Refund")f.Add("Site","Site / project",choices:Choices("Site"));
        if(head is "Employee Loan Repayment" or "Business Loan Repayment" or "Business Loan Received")f.Add("Instrument","Loan",choices:Choices("Instrument",$"Kind='{(head=="Employee Loan Repayment"?"Employee Loan":"Business Loan")}' AND Status='Active'"));
        if(head=="Business Loan Repayment"){f.Add("Interest","Interest included (INR)","money");f.Add("Charges","Charges included (INR)","money");}
        if(head=="Salary/Wages"){using var d=engine.Open();var choices=d.Table("SELECT r.Id,e.Name,p.Month,p.Year FROM PayrollRow r JOIN Employee e ON e.Id=r.EmployeeId JOIN Payroll p ON p.Id=r.PayrollId WHERE p.Status='Finalized' ORDER BY p.Day DESC").Rows.Cast<DataRow>().Select(r=>new Choice(Value.Long(r[0]),$"{r[1]} • {Value.Long(r[2]):00}-{r[3]}"));f.Add("Payroll","Salary month / employee",choices:choices);}
        if(head=="BG Charges")f.Add("BG","Bank guarantee",choices:Choices("BG"));
        if(head=="Expense Payment")f.Add("Category","Expense category",choices:Choices("Category"));
        f.Add("Mode","Payment mode",options:["NEFT","RTGS","IMPS","UPI","Cheque","Cash","Other"]);
        if(head=="Tax/Statutory Payment")f.Add("Reference","Statutory ledger",options:["EPF","ESIC","OCGST","OSGST","OIGST","DEDUCTION"]);else f.Add("Reference","Reference number");
        if(head.StartsWith("Other "))f.Add("Counter","Counter ledger",options:["INCOME","CAPITAL","ASSET","DEPOSIT","EXPENSE","CHARGES","INTEREST"]);
        if(head is "Customer Receipt" or "Supplier Payment")f.Add("Opening","Settle unallocated opening balance","bool");if(head=="Customer Refund")f.Add("Counter","Refund source",options:["AR","CUSTADV"]);f.Add("Remarks","Remarks","multiline");
        if(f.Fields.ContainsKey("Employee")){var label=new Label{Dock=DockStyle.Bottom,Height=45,Padding=new Padding(15),ForeColor=Ui.Teal};f.Controls.Add(label);void Bal(){Ui.Run(()=>{long id=f.N("Employee");label.Text=$"Advance outstanding: INR {Value.Display(engine.Balance("ADV",employee:id))}   |   Staff: INR {Value.Display(engine.Balance("STAFF",employee:id))}";});}((ComboBox)f.Fields["Employee"]).SelectedIndexChanged+=(_,_)=>Bal();if(((ComboBox)f.Fields["Employee"]).Items.Count>0)Bal();}
        f.Finish(x=>{long? id(string key)=>x.Fields.ContainsKey(key)?x.Id(key):null;long n(string key)=>x.Fields.ContainsKey(key)?x.N(key):0;List<AllocationInput>? allocations=null;if((head is "Customer Receipt" or "Supplier Payment")&&n("Opening")==0){allocations=Allocate(x.N("Party"),receipt?"Sales":"Purchase",x.N("Amount"));Value.Require(allocations!=null,"Allocation was cancelled. The receipt/payment was not posted.");}engine.Move(new(head,x.D("Day"),x.N("Amount"),x.N("Bank"),id("Party"),id("Employee"),id("Site"),id("Instrument"),id("Payroll"),id("Category"),id("BG"),n("Interest"),n("Charges"),x.S("Mode"),x.S("Reference"),x.S("Remarks"),allocations,x.Fields.ContainsKey("Counter")?x.S("Counter"):"",n("Opening")==1),receipt);},"Post transaction");f.ShowDialog(this);
    }
    List<AllocationInput>? Allocate(long party,string kind,long amount){using var d=engine.Open();var invoices=d.Table("SELECT Id,Number,Day,Total FROM Invoice WHERE PartyId=@p0 AND Kind=@p1 AND VoucherId IS NOT NULL AND Cancelled=0",party,kind);var t=new DataTable();t.Columns.Add("Id",typeof(long));t.Columns.Add("Invoice");t.Columns.Add("Date");t.Columns.Add("Outstanding",typeof(decimal));t.Columns.Add("Allocate",typeof(decimal));foreach(DataRow r in invoices.Rows){long outstanding=engine.Outstanding(Value.Long(r[0]));if(outstanding>0)t.Rows.Add(Value.Long(r[0]),r[1],Value.Date((int)Value.Long(r[2])),Value.Rupees(outstanding),0m);}using var f=new Form{Text="Allocate INR "+Value.Display(amount)+" to invoices",Width=850,Height=550,StartPosition=FormStartPosition.CenterParent};var grid=Ui.Grid();grid.DataSource=t;grid.ReadOnly=false;foreach(DataGridViewColumn c in grid.Columns)c.ReadOnly=c.Name!="Allocate";grid.Columns["Id"].Visible=false;List<AllocationInput>? result=null;var bar=Bar();bar.Dock=DockStyle.Bottom;bar.Controls.Add(Ui.Button("Use allocation",()=>{grid.EndEdit();f.BindingContext![t]!.EndCurrentEdit();var selected=t.Rows.Cast<DataRow>().Where(r=>Value.Dec(r["Allocate"])>0).Select(r=>new AllocationInput(Value.Long(r["Id"]),Value.Money(Value.Dec(r["Allocate"])))).ToList();Value.Require(selected.Sum(a=>a.Amount)==amount,"Allocated total must equal the receipt/payment amount.");result=selected;f.DialogResult=DialogResult.OK;},150));f.Controls.Add(grid);f.Controls.Add(bar);f.ShowDialog(this);return result;}
    void Transfer(){using var f=new Entry("Bank transfer — own accounts only");f.Add("Day","Date","date");f.Add("From","Source account",choices:Choices("Bank","Active=1"));f.Add("To","Destination account",choices:Choices("Bank","Active=1"));f.Add("Amount","Amount (INR)","money");f.Add("Reference","Reference");f.Finish(x=>engine.Transfer(x.D("Day"),x.N("From"),x.N("To"),x.N("Amount"),x.S("Reference")),"Post transfer");f.ShowDialog(this);}
    void SiteExpense(){using var f=new Entry("Site expense");f.Add("Day","Date","date");f.Add("Employee","Employee",choices:Choices("Employee","Active=1"));f.Add("Site","Site / project",choices:Choices("Site"));f.Add("Category","Expense category",choices:Choices("Category"));f.Add("Amount","Expense (INR)","money");f.Add("Bank","Paid from (None = staff advance)",choices:Choices("Bank","Active=1"),optional:true);f.Add("Remarks","Description / remarks","multiline");var balance=new Label{Dock=DockStyle.Bottom,Height=42,Padding=new Padding(15),ForeColor=Ui.Teal};f.Controls.Add(balance);void Update(){Ui.Run(()=>{if(f.Id("Employee")==null||f.Id("Site")==null)return;long b=engine.Balance("STAFF",employee:f.N("Employee"),site:f.N("Site"),through:f.D("Day"));balance.Text="Available advance: INR "+Value.Display(b)+"    After expense: INR "+Value.Display(b-f.N("Amount"));});}foreach(var key in new[]{"Employee","Site"})((ComboBox)f.Fields[key]).SelectedIndexChanged+=(_,_)=>Update();((NumericUpDown)f.Fields["Amount"]).ValueChanged+=(_,_)=>Update();f.Finish(x=>engine.SiteExpense(x.D("Day"),x.N("Employee"),x.N("Site"),x.N("Category"),x.N("Amount"),x.Id("Bank"),x.S("Remarks")),"Post expense");Update();f.ShowDialog(this);}
    void Instrument(string kind){using var f=new Entry("New "+kind);InstrumentFields(f,kind);f.Finish(x=>engine.CreateInstrument(InstrumentValues(x,kind)),kind=="Business Loan"?"Create loan account":"Create and post");f.ShowDialog(this);}
    void InstrumentFields(Entry f,string kind){f.Add("Number",kind+" number");f.Add("Day","Date","date");f.Add("Principal",kind=="Business Loan"?"Sanction amount (INR)":"Principal (INR)","money");if(kind!="Business Loan"){f.Add("Opening","Historical opening (no bank movement)","bool");f.Add("Bank","Paid from bank",choices:Choices("Bank","Active=1"),optional:true);}if(kind=="Employee Loan")f.Add("Employee","Employee",choices:Choices("Employee","Active=1"));f.Add("Rate","Interest rate %","percent");if(kind=="FD"){f.Add("Type","Lien type",options:["Free FD","Other Lien"]);f.Add("Maturity","Maturity date","date");f.Add("MaturityAmount","Expected maturity amount (INR)","money");}else{f.Add("EMI","Monthly recovery / EMI (INR)","money");f.Add("Recovery","Recovery start / next EMI date","date");f.Add("Installments","Number of installments","number");}if(kind=="Business Loan"){f.Add("Lender","Bank / lender");f.Add("Type","Loan type",options:["Term Loan","OD","CC","Vehicle Loan","Other"]);}f.Add("Remarks","Remarks","multiline");}
    InstrumentInput InstrumentValues(Entry x,string kind)=>new(kind,x.S("Number"),x.D("Day"),x.N("Principal"),kind=="Business Loan"?null:x.Id("Bank"),kind=="Employee Loan"?x.Id("Employee"):null,kind=="Business Loan"?x.S("Lender"):"",kind is "Business Loan" or "FD"?x.S("Type"):"",kind=="FD"?x.D("Maturity"):null,x.Dec("Rate"),kind=="FD"?x.N("MaturityAmount"):0,kind=="FD"?0:x.N("EMI"),kind=="FD"?null:x.D("Recovery"),kind=="FD"?0:x.D("Installments"),x.S("Remarks"),kind!="Business Loan"&&x.N("Opening")==1);
    void CloseFD(long id){using var f=new Entry("FD closure / renewal");f.Add("Day","Settlement date","date");f.Add("Bank","Credit to bank",choices:Choices("Bank","Active=1"));f.Add("Interest","Actual interest received (INR)","money");f.Add("Renew","Renew this FD","bool");f.Add("Number","New FD number (renewal)");f.Add("Principal","New principal (renewal, INR)","money");f.Add("Maturity","New maturity date","date");f.Add("Rate","New interest rate %","percent");f.Add("MaturityAmount","Expected maturity amount (INR)","money");f.Finish(x=>{if(x.N("Renew")==0)engine.CloseFD(id,x.D("Day"),x.N("Bank"),x.N("Interest"));else engine.RenewFD(id,x.D("Day"),x.N("Bank"),x.N("Interest"),new("FD",x.S("Number"),x.D("Day"),x.N("Principal"),x.N("Bank"),MaturityDay:x.D("Maturity"),Rate:x.Dec("Rate"),MaturityAmount:x.N("MaturityAmount")));});f.ShowDialog(this);}
    void BG(long? id=null){Dictionary<string,object?> init=[];if(id!=null){using var d=engine.Open();var r=d.Row("SELECT * FROM BG WHERE Id=@p0",id);init=r.Table.Columns.Cast<DataColumn>().ToDictionary(c=>c.ColumnName,c=>(object?)r[c]);}using var f=new Entry(id==null?"New bank guarantee":"Amend bank guarantee",init);f.Add("Number","BG number");f.Add("Day","BG date","date");f.Add("BankId","Bank",choices:Choices("Bank","Cash=0 AND Active=1"));f.Add("Branch","Branch");f.Add("Beneficiary","Beneficiary");f.Add("Amount","BG amount (INR)","money");f.Add("Type","BG type");f.Add("Purpose","Purpose / PO / contract");f.Add("ExpiryDay","Expiry date","date");f.Add("ClaimDay","Claim validity date","date");f.Add("Dispatch","Dispatch / courier / docket","multiline");f.Add("DeliveredDay","Delivered date","date",optional:true);f.Add("Confirmed","BG confirmation received","bool");f.Add("Remarks","Amendment reference / remarks","multiline");f.Finish(x=>engine.SaveBG(new(x.S("Number"),x.D("Day"),x.N("BankId"),x.S("Branch"),x.S("Beneficiary"),x.N("Amount"),x.S("Type"),x.S("Purpose"),x.D("ExpiryDay"),x.D("ClaimDay"),x.S("Dispatch"),x.Id("DeliveredDay") is long day?(int)day:null,x.N("Confirmed")==1,x.S("Remarks")),id));f.ShowDialog(this);}
    void LinkFD(long bg){using var f=new Entry("Link a fixed deposit to BG");f.Add("FD","Fixed deposit",choices:Choices("Instrument","Kind='FD' AND Status='Active'"));f.Add("Day","Lien date","date");f.Finish(x=>engine.LinkFD(bg,x.N("FD"),x.D("Day")));f.ShowDialog(this);}
}
